package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.operator.*;import com.intermarche.backoffice.domain.util.DateTimeProvider;
import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import org.junit.jupiter.api.Test;import java.util.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;import static io.restassured.RestAssured.given;
@QuarkusTest @jakarta.enterprise.inject.Typed(ShiftAndSupportWorkflowTest.class)
class ShiftAndSupportWorkflowTest extends MissionCoordinationTest {
 Map<String,Object> shift(){return given().auth().oauth2(f.picker()).get("/handling-orders/operator/shifts?storeId="+f.store()).then().statusCode(200).extract().jsonPath().getMap("$");}
 Map<String,Object> start(){return given().auth().oauth2(f.picker()).contentType("application/json").body(Map.of("storeId",f.store(),"action","START","requestKey",key())).post("/handling-orders/operator/shifts").then().statusCode(200).extract().jsonPath().getMap("$");}
 Map<String,Object> request(Map<String,Object> s,String action){return new LinkedHashMap<>(Map.of("storeId",f.store(),"shiftId",s.get("id"),"expectedRevision",s.get("revision"),"action",action,"requestKey",key()));}
 @Test void declaredWaitingDoesNotBecomeInferredInactivityAndRetriesDoNotOpenAnotherShift(){var prior=DateTimeProvider.getFixedDateTime();var t=LocalDateTime.now().withNano(0);try{DateTimeProvider.setFixedDateTime(t);var input=Map.of("storeId",f.store(),"action","START","requestKey",key());given().auth().oauth2(f.picker()).contentType("application/json").body(input).post("/handling-orders/operator/shifts").then().statusCode(200);given().auth().oauth2(f.picker()).contentType("application/json").body(input).post("/handling-orders/operator/shifts").then().statusCode(200);var s=shift();DateTimeProvider.setFixedDateTime(t.plusMinutes(10));var wait=request(s,"STATE");wait.put("state","WAIT_STOCK");given().auth().oauth2(f.picker()).contentType("application/json").body(wait).post("/handling-orders/operator/shifts").then().statusCode(200);DateTimeProvider.setFixedDateTime(t.plusMinutes(20));s=shift();assertEquals(600,((Number)((Map<?,?>)s.get("seconds")).get("PREPARATION")).intValue());assertEquals(600,((Number)((Map<?,?>)s.get("seconds")).get("WAIT_STOCK")).intValue());assertEquals("DECLARED",s.get("timeBasis"));QuarkusTransaction.requiringNew().run(()->assertEquals(1,OperatorShift.count("store.id",f.store())));}finally{if(prior==null)DateTimeProvider.clear();else DateTimeProvider.setFixedDateTime(prior);}}
 @Test void activePauseDurationIsNotTheTotalOfEarlierPauses(){var prior=DateTimeProvider.getFixedDateTime();var t=LocalDateTime.now().withNano(0);try{
  DateTimeProvider.setFixedDateTime(t);start();
  for(int step=0;step<3;step++){DateTimeProvider.setFixedDateTime(t.plusMinutes(new int[]{5,7,10}[step]));var input=request(shift(),"STATE");input.put("state",step==1?"PREPARATION":"BREAK");input.put("reason","Pause déclarée");given().auth().oauth2(f.picker()).contentType("application/json").body(input).post("/handling-orders/operator/shifts").then().statusCode(200);}
  DateTimeProvider.setFixedDateTime(t.plusMinutes(13));var s=shift();assertEquals(180,((Number)s.get("stateSeconds")).intValue());assertEquals(300,((Number)((Map<?,?>)s.get("seconds")).get("BREAK")).intValue());assertEquals("Pause déclarée",s.get("stateReason"));
 }finally{if(prior==null)DateTimeProvider.clear();else DateTimeProvider.setFixedDateTime(prior);}}
 @Test void shiftCountsPreparedLinesOnceAndKeepsTransfersSeparate(){line();start();picked();attach(f.second());var move=command("MOVE_ITEM");move.putAll(Map.of("itemId",f.item(),"toteCode",f.tote(),"targetToteCode",f.second()));command(move).then().statusCode(200);var s=shift();assertEquals(1,((Number)s.get("preparedLines")).intValue());assertTrue(((List<Map<String,Object>>)s.get("quantities")).stream().anyMatch(q->q.get("metric").equals("TRANSFERRED")));assertEquals(false,given().auth().oauth2(f.manager()).get("/handling-orders/operator/shifts?storeId="+f.store()).then().statusCode(200).extract().path("active"));}
 @Test void goalsAreManagerControlledAndVisibleToTheOperator(){var s=start();var goal=request(s,"GOAL");goal.put("goalLines",20);given().auth().oauth2(f.picker()).contentType("application/json").body(goal).put("/handling-orders/operator/shifts/goal").then().statusCode(403);given().auth().oauth2(f.manager()).contentType("application/json").body(goal).put("/handling-orders/operator/shifts/goal").then().statusCode(200);assertEquals(20,((Number)shift().get("goalLines")).intValue());}
 @Test void sendingADiagnosticNotifiesSupportOnceWithoutCopyingUnknownFields(){var data=new LinkedHashMap<String,Object>(Map.of("storeId",f.store(),"requestKey",key(),"screen","TERMINAL","sdk",35,"httpStatus",409,"errorCode","STALE_REVISION","token","SHOULD_NOT_PERSIST"));for(int i=0;i<2;i++)given().auth().oauth2(f.picker()).contentType("application/json").body(data).post("/handling-orders/operator/support/diagnostics").then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{assertEquals(1,OperatorDiagnostic.count("store.id",f.store()));var diagnostic=OperatorDiagnostic.<OperatorDiagnostic>find("store.id",f.store()).firstResult();assertFalse(diagnostic.payload.contains("SHOULD_NOT_PERSIST"));assertEquals(1,OperatorNotice.count("store.id=?1 and eventKey=?2",f.store(),"diagnostic:"+diagnostic.trackingId));});}
 @Test void existingServicePauseAndFinishAlsoCloseTheDeclaredIntervals(){var s=start();given().auth().oauth2(f.picker()).contentType("application/json").body(Map.of("storeId",f.store(),"state","PAUSED")).put("/handling-orders/operator/support/session").then().statusCode(200);assertEquals("BREAK",shift().get("state"));given().auth().oauth2(f.picker()).contentType("application/json").body(Map.of("storeId",f.store(),"state","FINISHED")).put("/handling-orders/operator/support/session").then().statusCode(200);assertEquals(false,shift().get("active"));}
}
